        // --- SISTEMA AUTO-REFRESH MULTIMODO ---
        function visualClickFeedback() {
            const dot = ui('pro-status-dot');
            if (dot) { dot.classList.remove('ia-pulse'); void dot.offsetWidth; dot.classList.add('ia-pulse'); }
        }

        function clickTabByTarget(target) {
            const targetText = target === 'llegada' ? 'Tickets en Llegada' : 'Returned tickets';
            function findAndClick(doc) {
                if (!doc) return false;
                let spans = doc.querySelectorAll('span.spanovoidoverflow.span');
                for (let span of spans) {
                    if (span.innerText && span.innerText.trim().toLowerCase() === targetText.toLowerCase()) {
                        const anchor = span.closest('a');
                        if (anchor) anchor.click(); else span.click();
                        return true;
                    }
                }
                let clicked = false;
                doc.querySelectorAll('iframe').forEach(f => { try { if (findAndClick(f.contentDocument)) clicked = true; } catch (e) {} });
                return clicked;
            }
            try { let s = findAndClick(window.top.document); if (s) visualClickFeedback(); }
            catch (e) { let s = findAndClick(document); if (s) visualClickFeedback(); }
        }

        const refreshCont = document.createElement("div");
        refreshCont.style.position = "relative"; refreshCont.style.display = "flex"; refreshCont.setAttribute("data-elemento-nombre", "Refresh");
        const btnRefreshMenu = document.createElement("button"); btnRefreshMenu.className = "ia-btn"; btnRefreshMenu.setAttribute("aria-haspopup", "true");
        btnRefreshMenu.innerHTML = iaIcon('refresh') + `<span>Refresh</span><span class="ia-dot" id="pro-status-dot"></span>` + iaIcon('chevron', 12);
        const subRefresh = document.createElement("div"); subRefresh.className = "ia-menu";

        [{ label: "Llegada", mode: "llegada" }, { label: "Returned", mode: "returned" }, { label: "Llegada + Returned", mode: "ambas" }, { label: "Off", mode: "off" }].forEach(cfg => {
            const b = document.createElement("button"); b.className = `ia-menu-item btn-mode-${cfg.mode}`; b.innerText = cfg.label;
            b.onclick = () => { setRefreshMode(cfg.mode); cerrarTodos(null); };
            subRefresh.appendChild(b);
        });

        btnRefreshMenu.onclick = (e) => { e.stopPropagation(); const ab = subRefresh.style.display === "none" || subRefresh.style.display === ""; cerrarTodos(subRefresh); subRefresh.style.display = ab ? "block" : "none"; btnRefreshMenu.setAttribute("aria-expanded", ab ? "true" : "false"); };
        btnRefreshMenu.setAttribute("aria-expanded", "false");
        subRefresh._onClose = () => btnRefreshMenu.setAttribute("aria-expanded", "false");
        subAbiertos.push(subRefresh); refreshCont.appendChild(btnRefreshMenu); refreshCont.appendChild(subRefresh); menu.appendChild(refreshCont);

        function updateRefreshUIState() {
            subRefresh.querySelectorAll('.ia-menu-item').forEach(btn => btn.classList.remove('is-active'));
            const activeBtn = subRefresh.querySelector(`.btn-mode-${currentRefreshState}`); if (activeBtn) activeBtn.classList.add('is-active');
            const dot = ui('pro-status-dot') || btnRefreshMenu.querySelector('#pro-status-dot');
            if (dot) {
                if (currentRefreshState !== 'off') { dot.classList.add('is-on'); btnRefreshMenu.classList.add('is-active'); }
                else { dot.classList.remove('is-on'); btnRefreshMenu.classList.remove('is-active'); }
            }
        }

        function setRefreshMode(mode) {
            currentRefreshState = mode; localStorage.setItem(STORAGE_KEY, mode); updateRefreshUIState();
            iaAnim(btnRefreshMenu.querySelector('.ia-icon[data-i="refresh"]'), [{ transform: 'rotate(0deg)' }, { transform: 'rotate(360deg)' }], { duration: 600 });
            if (clickTimer) { clearInterval(clickTimer); clickTimer = null; }
            if (mode !== 'off') {
                const interval = (mode === 'ambas') ? INTERVAL_AMBAS_MS : INTERVAL_SINGLE_MS;
                if (mode === 'ambas') { nextTabForAmbas = 'llegada'; clickTabByTarget(nextTabForAmbas); nextTabForAmbas = 'returned'; }
                else { clickTabByTarget(mode); }
                clickTimer = setInterval(() => {
                    if (currentRefreshState === 'ambas') { clickTabByTarget(nextTabForAmbas); nextTabForAmbas = nextTabForAmbas === 'llegada' ? 'returned' : 'llegada'; }
                    else { clickTabByTarget(currentRefreshState); }
                }, interval);
            }
        }
        updateRefreshUIState();
        if (currentRefreshState !== 'off') setRefreshMode(currentRefreshState);

        // --- MODAL CERRAR INCIDENCIA ---
        const cerrarCont = document.createElement("div"); cerrarCont.style.position = "relative"; cerrarCont.style.display = "flex"; cerrarCont.setAttribute("data-elemento-nombre", "CerrarIncidencia");
