            overlay.appendChild(box); SR.appendChild(overlay);

            popularSelectsCierre(box.querySelector('#oceane-select-etiqueta'), box.querySelector('#oceane-select-comentario'), box.querySelector('#oceane-select-estado'));
            popularCustomEtiquetas(box.querySelector('#oceane-select-custom-apertura'), box.querySelector('#oceane-select-custom-cierre'));
            box.querySelectorAll('select').forEach(iaDropdown);
            box.querySelectorAll('.ia-subpanel').forEach(iaSubpanel);
            iaEtiquetaCodigo(box.querySelector('#oceane-select-comentario'), box.querySelector('[data-label-codigo]'));
            vincularEstadoAEtiqueta(box.querySelector('#oceane-select-etiqueta'), box.querySelector('#oceane-select-estado'), box.querySelector('[data-hint-estado]'));
            vincularComentarioAEtiqueta(box.querySelector('#oceane-select-etiqueta'), box.querySelector('#oceane-select-comentario'), box.querySelector('[data-hint-comentario]'));
            vincularComentarioYEstado(box.querySelector('#oceane-select-etiqueta'), box.querySelector('#oceane-select-comentario'), box.querySelector('#oceane-select-estado'), box.querySelector('[data-hint-estado]'));
            box.querySelector('#oceane-input-roaming-etiqueta').addEventListener('input', (e) => { delete e.target.dataset.auto; box.querySelector('[data-hint-pais]').classList.add('ia-hidden'); });
