        function getHotkeyString(e) {
            let keys = [];
            if (e.ctrlKey) keys.push('ctrl');
            if (e.altKey) keys.push('alt');
            if (e.shiftKey) keys.push('shift');
            if (['Control', 'Alt', 'Shift', 'Meta'].includes(e.key)) return '';
            keys.push(e.key.toLowerCase());
            return keys.join('+');
        }

        if (!window.hotkeysIntervalCargado) {
            setInterval(() => {
                function bindKeys(doc) {
                    if (!doc) return;
                    let w = doc.defaultView;
                    if (w && !w.hotkeysOceaneListos) {
                        w.addEventListener('keydown', async (e) => {
                            // Adaptación Shadow DOM: el objetivo real del evento es el primero de composedPath()
                            const origen = (e.composedPath && e.composedPath()[0]) || e.target;
                            if (['INPUT', 'TEXTAREA'].includes(origen.tagName)) return;
                            const pressed = getHotkeyString(e);
                            if (!pressed) return;

                            const shortcuts = getShortcuts();
                            if (shortcuts[pressed]) {
                                e.preventDefault(); e.stopPropagation();
                                cerrarTodos(null);
                                btnMsg(btnCerrarIncidencia, 'Ejecutando atajo...', 'busy', 15000);

                                const datosDirectos = {
                                    etiqueta: shortcuts[pressed].etiqueta,
                                    comentario: shortcuts[pressed].comentario,
                                    estado: shortcuts[pressed].estado,
                                    esAtajo: true
                                };

                                nuevaFichaExcel();                    // un atajo = ticket nuevo
                                ejecutarCierreIncidencia(datosDirectos);
                            }
                        });
                        w.hotkeysOceaneListos = true;
                    }
                    try { doc.querySelectorAll('iframe').forEach(f => bindKeys(f.contentDocument)); } catch(e) {}
                }
                bindKeys(window.top.document);
            }, 1500);
            window.hotkeysIntervalCargado = true;
        }

